package com.meetspace.controller; import com.meetspace.dto.*; import com.meetspace.dto.EmployeeDtos.*; import com.meetspace.security.UserPrincipal; import com.meetspace.service.EmployeeService; import jakarta.validation.Valid; import org.springframework.security.core.annotation.AuthenticationPrincipal; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/employees") public class EmployeeController{private final EmployeeService s;public EmployeeController(EmployeeService s){this.s=s;}@GetMapping("/me") ApiResponse<Profile> me(@AuthenticationPrincipal UserPrincipal p){return ApiResponse.ok("Employee profile retrieved",s.me(p.id()));}@PutMapping("/me") ApiResponse<Profile> update(@AuthenticationPrincipal UserPrincipal p,@Valid @RequestBody Update x){return ApiResponse.ok("Employee profile updated",s.update(p.id(),x));}}